function currentSourceState(s){return (s.state==='unknown'||(s.buffering&&s.sourceState==='running'))?'unknown':s.sourceState??s.state;}
function renderConnection(s){
 s={...s,state:currentSourceState(s),rpm:s.sourceRpm===undefined?s.rpm:s.sourceRpm};
 const fullStamp=value=>value?new Intl.DateTimeFormat(lang==='zh'?'zh-CN':'en-GB',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(value):'—';
 put('connection-state',mode==='sim'?t('connectionSim'):connectionText(s));
 put('connection-response',hasAttempt?(responseStatus?'HTTP '+responseStatus:t('connectionNoResponse'))+' · '+(responseMs/1000).toFixed(2)+' s':t('connectionNotRead'));
 put('connection-received',fullStamp(lastSuccessAt));put('connection-observed',fullStamp(lastReceivedSample));put('connection-speed',mode==='sim'||s.state==='unknown'?'—':s.rpm.toFixed(1)+' '+t('rpmUnit'));
 const measurement=mode==='live'&&s.state!=='unknown'?raw?.measurement:null;
 const count=measurement?.cumulativeWorkUnits;
 put('connection-work',typeof count==='string'&&/^\d{1,40}$/.test(count)?new Intl.NumberFormat(lang==='zh'?'zh-CN':'en-GB').format(BigInt(count)):'—');
 put('connection-distance',Number.isFinite(measurement?.distanceMm)&&measurement.distanceMm>=0?(measurement.distanceMm/1e6).toFixed(2)+' '+(lang==='zh'?'公里':'km'):'—');
 $('connection-refresh').disabled=pending||mode==='sim';
 put('connection-refresh',t(pending?'updating':'connectionRefresh'));put('retry',t(pending?'updating':'refresh'));
}
